<script setup lang="ts">
import { CheckCircle2, Clock3, CreditCard, ShieldCheck } from '@lucide/vue'
import { onMounted, ref } from 'vue'
import api from '../api'
import BrandLogo from '../components/BrandLogo.vue'
import { useLocaleStore } from '../stores/locale'
const locale=useLocaleStore();const loading=ref(true);const plans=ref<any[]>([]);const subscription=ref<any>(null);const paymob=ref(false);const error=ref('');const busy=ref<number|null>(null)
async function load(){try{const response=(await api.get('/subscriptions')).data;plans.value=response.plans;subscription.value=response.subscription;paymob.value=response.paymob_available}finally{loading.value=false}}
async function choose(plan:any,cycle:'month'|'year'){busy.value=plan.id;error.value='';try{const response=(await api.post('/subscriptions/checkout',{plan_id:plan.id,billing_cycle:cycle})).data;if(response.checkout_url) window.location.assign(response.checkout_url)}catch(e:any){error.value=e.response?.data?.message||locale.tr('Unable to start checkout.')}finally{busy.value=null}}
onMounted(load)
</script>
<template><div class="subscription-page"><header><BrandLogo/><span><ShieldCheck/> {{locale.tr('Secure subscription management')}}</span></header><main><section class="subscription-hero"><div><small>{{locale.tr('ACADEMYHUB SUBSCRIPTIONS')}}</small><h1>{{subscription?locale.tr('Keep your academy moving.'):locale.tr('Choose the plan that fits your academy.')}}</h1><p>{{subscription?locale.tr('Your current access is shown below. Upgrade any time to unlock more centres, students and staff.'):locale.tr('Your trial or subscription controls access to the academy workspace.')}}</p></div><CreditCard/></section><div v-if="loading" class="loading-state"><span></span>{{locale.tr('Loading plans…')}}</div><template v-else><section v-if="subscription" class="subscription-current"><Clock3/><div><b>{{subscription.name}}</b><small>{{subscription.status==='trialing'?locale.tr('Free trial'):locale.tr('Active subscription')}} · {{locale.tr('Ends')}} {{new Date(subscription.ends_at).toLocaleDateString()}}</small></div></section><div v-if="error" class="form-error">{{error}}</div><section class="subscription-grid"><article v-for="plan in plans" :key="plan.id" class="subscription-card" :class="{featured:plan.is_featured,trial:plan.monthly_price_minor===0}"><span v-if="plan.is_featured" class="subscription-badge">{{locale.tr('Most popular')}}</span><small>{{plan.name}}</small><h2>{{plan.monthly_price_minor===0?locale.tr('Free'):((plan.monthly_price_minor/100).toFixed(0)+' EGP')}}<em v-if="plan.monthly_price_minor>0"> / {{locale.tr('month')}}</em></h2><p>{{plan.description}}</p><ul><li v-for="feature in plan.features||[]" :key="feature"><CheckCircle2/>{{feature}}</li></ul><button v-if="plan.monthly_price_minor===0" class="button secondary" disabled>{{locale.tr('14-day trial')}}</button><button v-else class="button primary" :disabled="!paymob||busy===plan.id" @click="choose(plan,'month')">{{busy===plan.id?locale.tr('Opening checkout…'):paymob?locale.tr('Subscribe now'):locale.tr('Payment setup pending')}}</button></article></section></template></main></div></template>
